INSERT INTO reading_passages
    (id, exam_version_id, title, subtitle, paragraphs, word_count, difficulty, topic, tags, passage_slot, modules)
VALUES
    ('rp-ir86-bioluminescence', 'ielts-2026-01', 'Living Light: The Science and Applications of Bioluminescence', 'How organisms produce cold light and how science puts it to use',
     '[{"label": "A", "text": "Across the planet, from pitch-black oceanic abysses to damp tropical forest floors, thousands of living species possess the remarkable ability to emit visible illumination. Known as bioluminescence, this phenomenon is distinct from incandescence, where light is released as a byproduct of thermal radiation. Bioluminescence is fundamentally a form of cold light, meaning that less than twenty percent of the generated energy is lost as heat, with the overwhelming remainder converted directly into photons. The reaction relies upon a specialized substrate called luciferin, which undergoes oxidation when catalyzed by the enzyme luciferase. In many organisms, auxiliary cofactors such as adenosine triphosphate (ATP) and magnesium ions are required to charge the substrate before the light-producing oxidation can occur. Variations of these biochemical compounds have evolved independently at least forty separate times throughout evolutionary history, underscoring the extraordinary survival utility of living radiance across disparate biological lineages."}, {"label": "B", "text": "While terrestrial examples such as fireflies and glowing fungi are well known to the public, the oceanic environment represents the true epicentre of bioluminescent diversity. Marine biologists estimate that more than seventy-five percent of pelagic creatures living between two hundred and one thousand metres below the surface possess light-emitting capabilities. In this twilight realm, often designated the mesopelagic zone, ambient sunlight barely penetrates, and bioluminescence serves as a vital tool for deception and defense. Many species of squid and small teleost fish utilize counterillumination, emitting light from ventral photophores that precisely matches the intensity and spectral wavelength of downwelling sunlight. By doing so, they eliminate their silhouettes, rendering themselves invisible to predators lurking in the depths beneath them. Other species adjust their ventral luminosity dynamically as passing clouds alter the downwelling sunlight overhead."}, {"label": "C", "text": "Beyond passive camouflage, bioluminescent emissions fulfill complex signaling and predation functions across marine and terrestrial habitats. The predatory anglerfish famously suspends a modified dorsal spine, known as an esca, over its gaping jaws; the glowing bulb harbors symbiotic bacteria that attract curious prey directly into striking range in the dark water. Conversely, other organisms employ dazzling bioluminescent displays as emergency deterrents against pursuers. Certain deep-sea jellyfish and ostracod crustaceans discharge clouds of radiant mucus when startled, momentarily blinding their pursuers or marking the attacker with luminescent stains that make them conspicuous to higher-level apex predators. On land, the synchronization of flashing among adult fireflies functions primarily as a courtship mechanism, enabling prospective mates to recognize species-specific rhythms across darkened meadows and riverbanks."}, {"label": "D", "text": "In the contemporary era, the biochemical apparatus of bioluminescence has transitioned from natural ecosystems into high-precision biomedical laboratories. When researchers successfully isolated the genetic sequence encoding luciferase from the North American firefly, they gained a revolutionary molecular tool known as a reporter gene. By inserting this sequence into experimental cells adjacent to a gene of interest, scientists can visually verify whether that specific gene is actively transcribed. If the target gene is activated, the cell synthesizes luciferase and produces a measurable glow when luciferin is introduced. This non-invasive method allows medical investigators to monitor tumour proliferation, track the progression of antibiotic resistance, and test pharmaceutical efficacy in living animal models in real time without resorting to destructive tissue sampling or invasive exploratory surgery."}, {"label": "E", "text": "Engineers and environmental scientists are now exploring macro-scale applications of bioluminescence that could transform sustainable technology and industrial monitoring. Water treatment facilities have developed biosensors using luminescent dinoflagellates; because these single-celled organisms dim when exposed to heavy metals, pesticides, or organic pollutants, their luminescence serves as an immediate, chemical-free indicator of aquatic toxicity. Concurrently, urban designers and biotechnologists are collaborating on experimental lighting initiatives. By transferring the genetic pathways of bioluminescent fungi into vascular houseplants, several research teams have created ornamental plants that emit a faint ambient glow, prompting speculation that genetic horticulture might one day illuminate urban footpaths and reduce grid electricity consumption in pedestrian parks."}, {"label": "F", "text": "However, genuine hurdles remain before bioluminescence can displace conventional artificial illumination in architecture. The chemical synthesis of light imposes a significant metabolic burden on any living organism. Genetically modified plants engineered to glow continuously often suffer from stunted growth, reduced photosynthetic efficiency, and structural frailty, as resources essential for cellular maintenance are diverted into photon production. Furthermore, the intensity of light currently produced remains several orders of magnitude below what is required for safe pedestrian navigation or municipal tasks. While bioluminescent lighting will undoubtedly remain a fixture in cellular analysis and environmental biosensing, its widespread adoption as an everyday architectural utility awaits major breakthroughs in synthetic biology, gene regulation, and energetic efficiency."}]'::jsonb,
     741, 'medium', 'Marine biology and biochemistry', ARRAY['IELTS Reading', 'Original practice'], 'custom', ARRAY['academic']),
    ('rp-ir86-lichens', 'ielts-2026-01', 'Partners in Survival: The Hidden Lives of Lichens', 'How a fungus and its partners colonise some of the harshest places on Earth',
     '[{"label": "A", "text": "Crusty orange patches on a garden wall, grey-green tufts hanging from a branch, pale rosettes spreading across a gravestone: lichens are among the most familiar sights in the natural world, yet they are widely misunderstood. Many people assume that they are a kind of moss, or a simple plant without roots. In fact, a lichen is not a single organism at all but a partnership. The main body is formed by a fungus, which provides structure and protection and absorbs water and minerals. Living among its threads is a photosynthetic partner, either a green alga or a cyanobacterium, which uses sunlight to make sugars that feed the whole association. Scientists have so far described around 20,000 species of lichen, and new ones are identified every year."}, {"label": "B", "text": "This partnership allows lichens to survive in conditions that few other living things can tolerate. They grow on bare rock in Antarctica, on the bark of rainforest trees and on the surface of hot deserts. Their secret is an unusual approach to water. Unlike most plants, lichens make no attempt to keep a constant water content. When their surroundings dry out, they simply dry out too and become dormant, sometimes for months or even years, without suffering serious harm. Once rain or dew returns, many species absorb water within minutes and resume photosynthesis almost immediately. This tolerance is so extreme that, in experiments on the International Space Station, some lichens survived long periods of exposure to the vacuum and radiation of space."}, {"label": "C", "text": "Lichens also play a quiet but essential part in the formation of soil. Because they need no soil themselves, they are often the first organisms to colonise newly exposed rock, which is why ecologists describe them as pioneer species. As they grow, lichens release weak acids that slowly break down the rock surface, while their bodies trap windblown dust. When they die, their remains add organic matter to this thin layer of weathered material, gradually creating conditions in which mosses, and later larger plants, can establish themselves. Such processes are extremely slow: some lichens expand by as little as a millimetre a year. Their steady growth has even been used to estimate the age of exposed rock surfaces, a technique known as lichenometry."}, {"label": "D", "text": "The same features that make lichens so hardy also make them unusually vulnerable to air pollution. Having no roots and no protective outer layer, they absorb water and nutrients directly from rain and the surrounding air, and with them any pollutants the air contains. During the nineteenth and twentieth centuries, many species vanished from industrial cities, where sulphur dioxide from burning coal made the air too acidic for them to survive. As clean-air laws reduced this pollution, lichens gradually returned, and their recovery is one of the clearest signs that such laws have worked. Today scientists use them to monitor a different problem, nitrogen pollution from traffic and farming, because some species thrive where nitrogen is abundant while others disappear."}, {"label": "E", "text": "People have found many uses for lichens over the centuries. In parts of Scotland and Scandinavia, they were traditionally boiled to produce dyes for wool, giving the cloth warm browns, oranges and purples. Litmus, the substance that turns red in acid and blue in alkali, was originally extracted from lichens and is still used to teach chemistry to schoolchildren. In the far north, lichens are a vital source of food in winter for reindeer and caribou, which dig through the snow to reach them. Some species contain compounds, such as usnic acid, that can kill certain bacteria, and they have been used in traditional medicine. However, it would be premature to expect lichen-based medicines to replace conventional antibiotics."}, {"label": "F", "text": "Despite their resilience, lichens face growing threats. Because they grow so slowly, communities damaged by trampling, construction or the collection of lichens for decoration can take decades to recover. Nitrogen pollution and a changing climate are altering which species can survive in many regions. At the same time, lichens continue to surprise the scientists who study them. In 2016, researchers reported that many common lichens contain a third partner, a type of yeast living in the outer layer of the lichen body, which had gone unnoticed for well over a century of study. The discovery suggests that these familiar organisms are more complex partnerships than anyone had imagined, and that much about them remains to be learned."}]'::jsonb,
     727, 'medium', 'Biology and ecology', ARRAY['IELTS Reading', 'Original practice'], 'custom', ARRAY['academic']),
    ('rp-ir86-qanats', 'ielts-2026-01', 'Underground Rivers: The Ancient Engineering of Qanats', 'How historic subterranean aqueducts enabled civilisation in arid landscapes',
     '[{"label": "A", "text": "In the hyper-arid expanses of the Iranian plateau, where annual rainfall rarely exceeds two hundred millimetres and scorching desert winds deplete open bodies of water, the flourishing of complex agrarian civilisations might appear historically impossible. Yet for nearly three millennia, prosperous oasis settlements, terraced orchards, and vibrant trading cities like Yazd and Gonabad thrived in this uncompromising geography. Their survival was made possible by an ingenious subterranean water-management technology known as the qanat (or kariz). Originating in the early first millennium BCE, this gravity-driven hydraulic system tapped into deep mountain aquifers and transported clean water across tens of kilometres beneath the desert floor, transforming arid barrens into productive cultural centres without consuming external mechanical energy or causing soil exhaustion."}, {"label": "B", "text": "The engineering logic of a qanat relies entirely upon the gentle manipulation of gravity. Construction began in elevated alluvial fans at the foothills of mountain ranges, where seasonal snowmelt seeped deep into permeable gravel layers. Expert hydrologists and miners, known as muqannis, would first dig a vertical exploratory shaft called the ''mother well'' until they struck the saturated water table, often lowering oil lamps into the shaft to verify that breathable air was present. Once a dependable underground source was identified, the muqannis embarked on the perilous task of excavating a subterranean conduit sloping very gradually downwards toward an agricultural lowland or settlement. By maintaining an extremely shallow gradient—often dropping barely one metre over every thousand metres of horizontal run—the channel ensured that water flowed steadily without acquiring sufficient velocity to erode the earthen tunnel walls, with vulnerable soft-soil sections reinforced by baked ceramic rings."}, {"label": "C", "text": "Crucial to both the construction and ongoing maintenance of the qanat was an alignment of vertical shafts puncturing the desert surface at regular intervals of twenty to fifty metres. These shafts served multiple engineering imperatives. During the initial excavation, they provided essential ventilation for the subterranean diggers working in low-oxygen conditions and functioned as vertical hoist conduits through which excavated soil and spoil were drawn upward in leather buckets. Once the channel was operational, the surface openings permitted maintenance crews to descend and clear accumulated silt or repair tunnel collapses. The raised dirt rims surrounding each shaft also prevented desert flash-flood waters from washing surface debris into the water supply. Seen from an aircraft today, these lines of crater-like mounds resemble strings of giant beads stretching across barren desert plains, demarcating the course of life-giving water hidden deep below."}, {"label": "D", "text": "The subterranean path offered decisive hydrological advantages over conventional surface canals. In an environment where surface evaporation rates can exceed three metres of standing water per year, sheltering the stream beneath tens of metres of insulating earth prevented catastrophic evaporative loss. Furthermore, keeping the water confined within dark subterranean galleries protected it from airborne desert dust, organic debris, and disease-carrying parasites, delivering crisp, potable drinking water directly to public distribution basins. Upon reaching urban settlements, qanat streams frequently fed into architectural cooling structures, such as windcatchers (badgirs) and dome-roofed subterranean icehouses (yakhchals), which utilized evaporative cooling to store winter ice well into the blazing summer months, while also cooling underground living basements called sardabs."}, {"label": "E", "text": "Maintaining a functional qanat required sophisticated communal governance and precise legal agreements that fostered remarkable social cohesion. Water emerging from the mouth of the tunnel was partitioned among landowning families according to strict temporal shares, measured meticulously using water clocks (clepsydras) supervised by an elected water official known as a mirab. Because a single qanat could take decades to excavate and demanded perpetual collective labour to clear collapsing sediments, communities could not afford internal feuds. Rights to irrigation flows were codified in customary law, establishing mutual obligations between upstream and downstream farmers that endured across generations, making the qanat as much a social institution as a physical infrastructure, sustained by shared community endowments."}, {"label": "F", "text": "Despite their enduring efficacy across centuries, qanats faced rapid decline throughout the mid-twentieth century following the widespread introduction of mechanized diesel pumps and deep tube wells. These modern motorized wells extracted water indiscriminately from deep subterranean aquifers, drastically dropping regional water tables far below the reach of ancient gravity-fed conduits. Thousands of historic qanats consequently ran dry, leading to soil salinization and the abandonment of historic desert oases. Today, however, growing recognition of groundwater overexploitation has prompted a resurgence of interest in qanat engineering. International conservation agencies and hydrological engineers argue that these ancient systems offer timeless lessons in passive sustainability, demonstrating how human communities can harvest groundwater in exact equilibrium with natural recharge rates while preserving fragile desert ecologies."}]'::jsonb,
     752, 'medium', 'Archaeology and hydraulic engineering', ARRAY['IELTS Reading', 'Original practice'], 'custom', ARRAY['academic']),
    ('rp-ir86-mycelium', 'ielts-2026-01', 'Nature''s Network: The Ecological Power of Mycelium', 'The underground fungal webs that sustain forests and inspire materials science',
     '[{"label": "A", "text": "Beneath the damp leaf litter of temperate woodlands and through the upper soil layers of grasslands lies a biological architecture of staggering scale and complexity. While most people recognize fungi solely by the mushrooms that erupt periodically above ground, these reproductive fruit bodies represent merely the fleeting tip of an immense subterranean organism. The true vegetative body of a fungus consists of mycelium—an intricate web of microscopic, branching filaments termed hyphae. A single cubic centimetre of healthy woodland soil can harbor kilometres of these thread-like strands. Extending outwards in search of nutrients, mycelial networks interlace with mineral particles, organic debris, and plant roots, forming a vast living matrix that underpins terrestrial plant ecology and binds loose topsoil against erosive runoff."}, {"label": "B", "text": "The ecological supremacy of mycelium stems from its capacity to forge mutualistic alliances with flora across both pristine wilderness and managed agriculture. In mycorrhizal associations, fungal hyphae envelop or physically penetrate the root tips of trees and herbaceous plants, fundamentally expanding the root surface area by hundreds of times. Possessing specialized digestive enzymes, mycelium breaks down tightly bound minerals in rocks and soil—particularly phosphorus, nitrogen, and micronutrients—and delivers them directly to the host plant in bioavailable form. In return, the autotrophic plant transfers photosynthetically produced sugars and carbon compounds to the heterotrophic fungus. Ecologists estimate that upwards of ninety percent of terrestrial plant species depend directly upon mycorrhizal fungi for optimal growth, disease resistance, and environmental stress resistance."}, {"label": "C", "text": "Some ecologists go further, arguing that these subterranean fungal pathways link whole woodland communities into a resource-sharing network, popularly dubbed the ''wood wide web''. Isotopic labelling experiments have shown that carbon and nitrogen can pass through mycelial connections from one tree to another, and several studies have reported mature canopy trees apparently supplying sugars to young saplings growing in deep shade. Other experiments suggest that when insect pests attack a tree, warning compounds may travel through the network, prompting neighbouring trees to produce defensive tannins before the infestation reaches them. These ideas nevertheless remain contested. Critics point out that many of the studies were small or carried out under controlled conditions, that chemicals can also move between roots through the soil itself, and that the quantities transferred in natural forests may be too small to matter. For now, the image of the forest as a single cooperative organism is best treated as a promising hypothesis rather than an established fact."}, {"label": "D", "text": "In addition to supporting forest health, mycelial networks exhibit profound capabilities in chemical degradation through a discipline known as mycoremediation. Fungi are nature''s supreme decomposers, synthesizing powerful extracellular enzymes—most notably lignin peroxidase and laccase—that evolved to crack open the tough, resilient chemical bonds of wood lignin. Because the complex ring structures of lignin chemically resemble synthetic petrochemical contaminants, these same fungal enzymes can decompose hazardous industrial pollutants. Controlled trials have proven that selected strains of oyster mushrooms and white-rot fungi can neutralize toxic crude oil spills, break down synthetic pesticides, and degrade carcinogenic dioxins into harmless carbon dioxide, water, and organic compost, offering a biological alternative to hazardous soil incineration."}, {"label": "E", "text": "Inspired by these natural structural and biochemical characteristics, materials scientists are pioneering mycelium-based bio-fabrication as a renewable substitute for environmentally damaging synthetic products. In industrial manufacturing, agricultural byproducts such as hemp shives, corn husks, or sawdust are inoculated with fungal spores and placed into shaped moulds. Over several days, the fungal hyphae consume part of the biomass and weave the remaining particles into a dense, rigid composite. Once fully colonised, the material is baked in low-temperature kilns to deactivate the fungus, yielding a lightweight, durable, and naturally fire-retardant substance. Global logistics companies are already adopting mycelium packaging as a fully compostable replacement for expanded polystyrene foam, with fashion houses even testing fungal leather alternatives."}, {"label": "F", "text": "The frontier of mycelial engineering is now expanding into architecture and acoustic design. Researchers have fabricated mycelium acoustic wall tiles that outperform standard commercial foam in sound absorption, alongside lightweight structural blocks capable of bearing modest compressive loads in internal non-loadbearing walls. Proponents envision circular buildings grown from local agricultural waste that can naturally return to the soil at the conclusion of their lifespan without generating landfill debris. Nevertheless, substantial commercial hurdles remain. Ensuring consistent structural density across large industrial batches requires stringent atmospheric control, and prolonged exposure to exterior moisture can trigger fungal rehydration or mould colonization if bio-composites are not sealed with bio-based water-repellent polymers. Scaling up bio-fabrication requires refining these coating techniques while keeping production economically competitive against petroleum plastics."}]'::jsonb,
     750, 'medium', 'Mycology and sustainable materials', ARRAY['IELTS Reading', 'Original practice'], 'custom', ARRAY['academic']),
    ('rp-ir86-ancientglass', 'ielts-2026-01', 'Molten Alchemy: The Evolution of Ancient Glassmaking', 'From prized Mediterranean luxury to mass-produced Roman utility',
     '[{"label": "A", "text": "For archaeologists investigating ancient technologies, few materials illustrate the trajectory of human pyrotechnic mastery as vividly as glass. Unlike pottery, which requires relatively modest kiln temperatures to fire clay, the production of true vitreous glass demands temperatures exceeding one thousand degrees Celsius alongside an exacting chemical recipe. The earliest synthetic vitreous objects, dating to the late third millennium BCE in Mesopotamia and Egypt, were non-transparent beads and amulets made from faience—a glazed ceramic precursor. By roughly 1500 BCE, true glass vessels began appearing in royal workshops across the eastern Mediterranean. These early containers were not blown but laboriously crafted using the core-formed technique: molten glass threads were coiled around a removable core of clay and organic matter, then repeatedly reheated and smoothed against flat stone marvers, producing miniature perfume flasks decorated with festive dragged zigzag trails."}, {"label": "B", "text": "The primary chemistry of ancient glass was remarkably consistent across cultures, comprising three indispensable components: silica, an alkaline flux, and a stabilizing agent. Silica, typically sourced from quartz pebbles or pure quartz-rich sands, provided the structural network of the glass. However, quartz melts at an intractable 1,700 degrees Celsius, a temperature far beyond the capability of Bronze Age furnaces. Glassmakers therefore added an alkaline flux to lower the operational melting point. In Bronze Age Egypt and Mesopotamia, this flux was obtained from the ashes of halophytic desert plants rich in soda and potash. Stabilizers, principally calcium oxide (lime), were inadvertently introduced as crushed seashells or calcite grains embedded in beach sand, preventing the glass from slowly dissolving in water and ensuring durable preservation over millennia."}, {"label": "C", "text": "Because raw glass was difficult to manufacture, its distribution was initially restricted to royal palaces and sacred temple treasuries. Early glass vessels were treated as synthetic gemstones, valued on par with lapis lazuli and turquoise. Skilled artisans added metallic oxides to replicate prestigious minerals: cobalt and copper yielded vibrant royal blues and turquoises, while manganese oxide generated royal purples or acted as a decolourizing agent to neutralize greenish iron impurities. The high status of glass is confirmed by diplomatic correspondence discovered at Tell el-Amarna in Egypt, where Near Eastern monarchs exchanged raw ingots of blue glass as diplomatic gifts alongside gold and thoroughbred horses. The famous Late Bronze Age Uluburun shipwreck discovered off the Anatolian coast contained over one hundred and seventy discs of raw Levantine blue glass meant for royal trade."}, {"label": "D", "text": "The transformative epoch in glass history arrived in the mid-first century BCE along the Syro-Palestinian coast with the invention of the blowpipe. By inflating a gathered glob of molten glass at the end of a hollow iron tube, artisans could shape a vessel in mere minutes rather than the days required by core-forming. This technical breakthrough coincided with the consolidation of the Roman Empire, which established vast, unified trade routes and an immense consumer market. Glassblowing revolutionized the economics of production: containers could be made far thinner, lighter, and with substantially less raw material. Within a century, glass shifted from an exclusive aristocratic luxury into a ubiquitous commercial commodity used throughout the Mediterranean basin for utilitarian tableware, storage bottles, window panes, and cosmetic unguents."}, {"label": "E", "text": "To satisfy this booming consumer demand, the Roman glass industry developed a two-tiered manufacturing model based on industrial geographical division. Primary production centres were established in coastal regions where high-purity quartz sand and natural mineral natron—an evaporite salt harvested from Egyptian dry lakebeds—were abundant. In colossal tank furnaces burning continuously for weeks, hundreds of tonnes of raw glass were melted into gigantic solid blocks, then cracked into transportable chunks. These raw chunks were subsequently shipped across maritime trade lanes to secondary urban workshops throughout Italy, Gaul, and Roman Britain, where localized artisans remelted the cullet to blow domestic vessels customized to local consumer preferences, supported by high-volume recycling of broken domestic glassware."}, {"label": "F", "text": "Today, advanced analytical techniques allow archaeometrists to reconstruct ancient glass trade routes with astounding accuracy. Using inductively coupled plasma mass spectrometry and thermal ionization mass spectrometry, scientists measure trace elements and isotopic ratios—specifically neodymium, strontium, and lead isotopes—within excavated glass sherds. Because different sand beds and mineral sources possess distinct geological isotopic fingerprints, researchers can match a Roman vessel found in northern Britain to the exact Levantine beach where its raw sand was quarried two thousand years ago. In this manner, ancient glass continues to provide invaluable evidence of prehistoric industrial logistics, global trade integration, and technological dissemination across ancient continents."}]'::jsonb,
     736, 'medium', 'Ancient history and materials technology', ARRAY['IELTS Reading', 'Original practice'], 'custom', ARRAY['academic']),
    ('rp-ir86-glaciers', 'ielts-2026-01', 'The Anatomy of Glaciers: Sentinels of Global Climate', 'The formation, dynamics, and hydrological significance of mountain ice',
     '[{"label": "A", "text": "Occupying roughly ten percent of the planet''s total land area, glaciers represent some of the most dynamic physical structures on Earth. While they appear from a distance to be static masses of frozen snow, glaciers are in truth colossal rivers of ice that deform, flow, and remodel terrestrial topography over geological epochs. The metamorphosis from fragile winter snowflake to dense glacial ice is a protracted physical process spanning decades or centuries. In high-altitude alpine regions and polar ice sheets, perennial snow accumulates in sheltered hollows where summer temperatures fail to induce complete melting. As successive seasonal snowfalls pile up, the weight of overlying layers exerts intense pressure on the bottom strata, expelling trapped atmospheric air. The loose crystals gradually recrystallize into a granular intermediate state known as firn, which eventually coalesces under extreme lithostatic compression into solid, blue glacial ice characterized by interlocking crystal lattices."}, {"label": "B", "text": "Once a mass of ice reaches a critical thickness of approximately thirty metres, its sheer mass overcomes internal friction, initiating downhill movement under the influence of gravity. This displacement occurs through two distinct mechanical regimes: internal plastic deformation and basal sliding. In the colder, deeper zones of the glacier, the ice behaves as a high-viscosity plastic fluid; under sustained differential pressure, individual microscopic ice crystals slip along internal cleavage planes, allowing the entire mass to creep slowly forward without fracturing. Conversely, the brittle upper fifty metres of the glacier cannot deform plastically, leading to the formation of gaping crevasses as the ice stretches over uneven bedrock. At the glacier''s base, meltwater generated by geothermal heat and frictional pressure acts as a pressurized hydraulic lubricant, facilitating basal sliding wherein the entire frozen monolith glides smoothly across the underlying bedrock."}, {"label": "C", "text": "A glacier functions as an open thermodynamic system governed by an annual mass balance—the algebraic difference between accumulation and ablation. The upper, high-elevation sector where snowfall exceeds annual melting is designated the accumulation zone. Downslope, separated by an equilibrium line where annual mass gain exactly equals mass loss, lies the ablation zone. Here, the glacier sheds mass through sublimation, evaporation, meltwater runoff, and, where ice margins meet open water, the dramatic calving of icebergs. The position of the terminus (the glacier''s front snout) serves as a sensitive visual barometer of regional climate trends: when accumulation outpaces ablation over a multi-year cycle, the snout advances down the valley; conversely, when ablation dominates, the terminus recedes upslope."}, {"label": "D", "text": "The ecological and hydrological significance of alpine glaciers is immense, earning them the moniker ''natural water towers'' of the planet. Throughout the arid summer months, when seasonal rainfall is negligible and lowland river tributaries run dry, glacial meltwater provides a dependable baseline discharge for major river basins across the Andes, the Alps, and the Himalayas. Billions of people living downstream depend directly upon this regulated alpine meltwater for drinking reserves, agricultural irrigation, and hydroelectric power generation. Furthermore, glaciers act as natural temperature regulators in mountainous regions, reflecting vast quantities of incoming solar radiation back into space through their high surface albedo."}, {"label": "E", "text": "In the modern era of glaciology, field scientists rely extensively on spaceborne remote sensing technologies to monitor ice dynamics across remote mountain ranges. Satellite radar altimetry and optical stereoscopy measure millimeter-scale changes in glacier elevation, while orbital gravimetry missions, such as NASA''s GRACE satellites, calculate mass fluctuations by detecting minute variations in Earth''s gravitational field over ice sheets. These orbital observations reveal that the overwhelming majority of alpine glaciers worldwide are currently experiencing rapid, unprecedented mass deficits, with thinning rates accelerating over recent decades in response to atmospheric and oceanic warming."}, {"label": "F", "text": "The accelerating retreat of mountain glaciers carries profound risks for surrounding mountain communities. As glaciers recede rapidly, meltwater often collects behind unstable dams of loose glacial debris and morainic boulders, creating perilous proglacial lakes. If an avalanche, rockfall, or earthquake breaches these fragile natural dams, it triggers a catastrophic glacial lake outburst flood (GLOF), unleashing millions of cubic metres of water and boulders on downstream villages with virtually no advance warning. Beyond these acute disasters, the long-term depletion of glacier reserves threatens chronic water insecurity across major agricultural belts once peak water is passed. Preserving mountain ecosystems and constructing early-warning flood infrastructure represents one of the most pressing civil engineering challenges of the twenty-first century."}]'::jsonb,
     706, 'medium', 'Glaciology and physical geography', ARRAY['IELTS Reading', 'Original practice'], 'custom', ARRAY['academic']),
    ('rp-ir86-biomimicry', 'ielts-2026-01', 'Borrowed from Biology: The Rise of Biomimetic Architecture', 'How structural and climatic adaptations in nature inspire human building design',
     '[{"label": "A", "text": "For millennia, human builders derived architectural inspiration from nature primarily through ornamental imitation: carving lotus petals into stone columns, sculpting acanthus leaves upon classical capitals, or painting floral motifs along palace ceilings. While visually striking, these artistic tributes were superficial, borrowing the decorative forms of the natural world without engaging with its functional mechanics. Over the past three decades, however, a profound philosophical shift has taken root across the architectural discipline. Popularized by naturalists and sustainable designers like Janine Benyus, biomimetic architecture treats nature not as an aesthetic catalogue, but as an exhaustive database of proven engineering solutions. Having undergone 3.8 billion years of evolutionary refinement, biological organisms have developed exquisite mechanisms to regulate temperature, maximize structural strength, and conserve vital resources while consuming minimal energy."}, {"label": "B", "text": "One of the most celebrated real-world demonstrations of biomimetic engineering is the Eastgate Centre, an expansive commercial and retail complex constructed in Harare, Zimbabwe. Designed by architect Mick Pearce in collaboration with engineers from Arup, the building operates without any conventional mechanical air conditioning systems, despite experiencing severe equatorial temperature swings. Pearce drew inspiration from the towering earthen mounds built by macrotermes termites. These social insects maintain a constant internal nursery temperature of thirty degrees Celsius while ambient exterior temperatures fluctuate from freezing at night to over forty degrees during the day. The termites achieve this homeostatic feat through a network of vertical flues and convective air channels. Mimicking this principle, the Eastgate Centre utilizes concrete thermal mass to absorb heat during the day, which is systematically vented out through high chimneys at night by natural convective currents, consuming thirty-five percent less energy than conventional office blocks in Harare."}, {"label": "C", "text": "In addition to thermal regulation, evolutionary biology provides remarkable templates for structural optimization that conserve costly building materials. Conventional structural engineering typically relies on uniform geometric beams and monolithic concrete pillars, resulting in substantial material redundancy. In contrast, natural structures such as mammalian bones and old-growth trees exhibit adaptive growth: they deposit structural tissue strictly along lines of mechanical stress while eliminating material from unstressed voids, following what biomechanists call the axiom of uniform stress. Modern structural software now replicates this biological efficiency through topological optimization algorithms. By iteratively trimming redundant material from digital structural models, engineers can design complex, bone-like steel joints and floor slabs that reduce overall building weight by up to forty percent without sacrificing load-bearing safety."}, {"label": "D", "text": "Biomimetic principles are equally revolutionizing the external envelopes and facades of contemporary buildings. The micro-textured surface of the sacred lotus leaf provides a quintessential model for building maintenance: despite thriving in muddy tropical ponds, the leaf remains immaculately clean because microscopic wax papillations minimize the contact area between water droplets and the surface. Raindrops ball up and roll effortlessly across the foliage, washing away adhered dirt particles. Paint and glass manufacturers have synthesized facade coatings that recreate this hydrophobic ''lotus effect''. Exterior building envelopes treated with these nano-textured coatings shed grime automatically during ordinary rainstorms, dramatically curtailing municipal water consumption and eliminating the need for caustic chemical detergents on high-rise facades."}, {"label": "E", "text": "In hyper-arid regions grappling with acute water scarcity, architects are looking to desert fauna for passive moisture harvesting systems. The fog-basking beetle of the Namib Desert survives in one of the driest habitats on Earth by condensing atmospheric fog on its specialized carapace. The beetle''s shell features an alternating array of microscopic hydrophilic peaks that attract suspended water droplets and waxy hydrophobic troughs that funnel accumulated moisture into the beetle''s mouth. Environmental engineers have translated this dual-texture architecture into large-scale fog-harvesting mesh netting and facade panels. Deployed in coastal desert communities in Chile and Morocco, these biomimetic collectors harvest hundreds of litres of clean potable water daily directly from coastal sea fog without using electrical pumps, supplying smallholder farms and domestic reserves."}, {"label": "F", "text": "Despite these compelling case studies, integrating biomimicry into mainstream construction remains challenging. Biological systems solve multi-variable physical problems holistically, whereas human construction industries are fragmented across specialized subcontractors and rigid municipal building codes. Furthermore, replicating fine biological microstructures—such as nano-scale hydrophobic textures or organic cellular lattices—demands advanced digital fabrication tools, including large-scale three-dimensional printing, which remain capital-intensive. The ultimate promise of biomimetic architecture lies in bridging this gap: moving beyond isolated demonstration projects toward systemic industrial design that respects natural ecological boundaries and minimizes humanity''s planetary footprint in an era of rapid climate change."}]'::jsonb,
     725, 'medium', 'Architecture and engineering', ARRAY['IELTS Reading', 'Original practice'], 'custom', ARRAY['academic']),
    ('rp-ir86-peatlands', 'ielts-2026-01', 'Sinks and Silt: The Global Importance of Peatlands', 'Why waterlogged bogs hold more carbon than all the world''s forests combined',
     '[{"label": "A", "text": "Covering barely three percent of the Earth''s terrestrial land surface, peatlands are easily overlooked wetland environments, often dismissed in popular folklore as bleak, treacherous bogs and dismal swamps. Yet beneath their unassuming mossy surfaces lies the planet''s most efficient terrestrial carbon sequestration mechanism. Peatlands—which encompass upland blanket bogs, lowland raised bogs, mineral-rich fens, and vast tropical swamp forests across the Congo Basin and Southeast Asia—store more than six hundred gigatonnes of carbon in their subterranean layers. To place this astronomical figure in perspective, this specialized ecosystem harbors twice as much carbon as the total biomass of all global forests combined. Understanding how peat forms, functions, and degrades has consequently emerged as a primary focus in global climate mitigation research and wetland conservation biology."}, {"label": "B", "text": "The secret to peat''s extraordinary capacity for carbon retention lies in a single geochemical condition: permanent waterlogging. In standard terrestrial environments, when plants die, soil organisms such as aerobic bacteria, fungi, and earthworms rapidly decompose the dead organic matter, consuming oxygen and returning carbon dioxide to the atmosphere. In peatlands, however, a high water table submerges plant residues beneath an anoxic aquatic layer where atmospheric oxygen cannot penetrate. Microbial activity slows to an infinitesimal pace in these oxygen-depleted, acidic waters. Over millenia, genera such as Sphagnum moss act as ecological architects: living moss releases organic acids that suppress rival vegetation and resist microbial breakdown. As successive generations of dead moss and sedges accumulate without rotting, they compress into a dense, carbon-dense organic stratum known as peat, accumulating at a sluggish rate of barely one millimetre per year, preserving ancient organic matter so thoroughly that prehistoric wooden artifacts and bog bodies remain intact."}, {"label": "C", "text": "Beyond their paramount role as planetary carbon vaults, intact peatlands perform irreplaceable ecological and hydrological services. Acting as natural sponge landscapes, pristine bogs absorb torrential precipitation during heavy storm events, buffering downstream valleys against flash flooding while sustaining baseline streamflow during summer droughts. As water filters slowly through peat''s spongy fibrous matrix, sediments, dissolved heavy metals, and particulate pollutants are trapped, discharging crystal-clear drinking water into municipal catchment reservoirs across mountainous regions. Peatlands also constitute unique biological sanctuaries: the harsh, acidic, nutrient-deficient conditions support specialized evolutionary oddities, including insectivorous plants like sundews and pitcher plants that capture insects to obtain nitrogen unavailable in the waterlogged soil."}, {"label": "D", "text": "Despite their immense ecological worth, peatlands have endured centuries of widespread human destruction. Historically viewed as unproductive wastelands, vast expanses of peat across northern Europe, North America, and Southeast Asia were deliberately excavated with deep drainage ditches to lower the water table for commercial agriculture and pine plantations. In countries such as Ireland and Finland, peat was also strip-mined on an industrial scale using heavy machinery, dried into fuel briquettes, and burned in thermal power stations to generate electricity for national grids. In tropical regions, particularly throughout Indonesia and Malaysia, extensive logging and drainage of peat swamp forests have made way for massive commercial oil palm and acacia monocultures, destroying vital habitats for endangered primates."}, {"label": "E", "text": "The environmental consequences of draining peatlands are swift and catastrophic. When the insulating water table drops, atmospheric oxygen immediately permeates the previously anoxic peat matrix. Latent aerobic bacteria revive, consuming centuries of accumulated organic matter in a rapid combustion-like oxidation process that releases immense plumes of carbon dioxide directly into the atmosphere. Drained peat also contracts and subsides physically, dropping land levels by several centimetres each year and increasing vulnerability to coastal seawater intrusion and foundation cracking. Most alarming are subterranean peat fires: dried peat becomes intensely flammable, sparking smouldering underground blazes that can burn undetected for months, resisting surface firefighting efforts and choking entire metropolitan regions in hazardous toxic haze."}, {"label": "F", "text": "Confronted by these mounting crises, an international ecological movement has emerged to rehabilitate degraded bogs through a process known as rewetting. Hydrologists block historic drainage canals with peat dams, timber bunds, and plastic piling to raise the groundwater table back to surface level. Once saturated conditions are re-established, indigenous vegetation like Sphagnum moss quickly recolonizes the landscape, halting aerobic oxidation and reviving active carbon accumulation. In areas where local economies rely on peatland farming, agronomists are pioneering paludiculture—the productive commercial cultivation of wetland crops, such as reed canary grass for biomass fuel and cattails for sustainable thermal building insulation. By harmonizing ecological restoration with commercial utility, rewetting offers a viable blueprint for securing humanity''s greatest subterranean carbon store under international climate conventions."}]'::jsonb,
     732, 'medium', 'Environmental science and climatology', ARRAY['IELTS Reading', 'Original practice'], 'custom', ARRAY['academic']),
    ('rp-ir86-forecasting', 'ielts-2026-01', 'Reading the Sky: How Weather Forecasting Became a Science', 'From storm warnings to supercomputers',
     '[{"label": "A", "text": "For most of human history, predicting the weather depended on local observation and inherited wisdom. Farmers and sailors watched the colour of the sky, the behaviour of animals and the shape of clouds, and passed their knowledge on in sayings such as ''red sky at night, shepherd''s delight''. Some of these sayings contain a grain of truth, since they reflect patterns that genuinely tend to precede changes in the weather. From the seventeenth century, the barometer allowed people to measure air pressure, and a falling reading came to be understood as a warning of unsettled conditions. Yet a single observer could see only the sky above them. The real obstacle to forecasting was that information about approaching weather could not travel faster than the weather itself. That changed in the 1840s, when the electric telegraph made it possible to collect observations from distant places within hours."}, {"label": "B", "text": "One of the first people to exploit this opportunity was Robert FitzRoy, who had earlier commanded HMS Beagle on the voyage that carried Charles Darwin around the world. In 1854 FitzRoy was appointed to lead a new government department collecting weather data at sea. Five years later, a violent storm wrecked the ship Royal Charter off the coast of Wales with the loss of hundreds of lives, and FitzRoy became convinced that such disasters could be prevented by warning ports in advance. He organised a network of coastal stations linked by telegraph, introduced public storm warnings, and began publishing daily forecasts in The Times newspaper in 1861. He is also credited with introducing the word ''forecast'' itself. His predictions were often wrong, however, and he faced harsh criticism from scientists and the press. Few people today remember his name, yet FitzRoy surely deserves far more credit than he received in his lifetime."}, {"label": "C", "text": "At the beginning of the twentieth century, the Norwegian scientist Vilhelm Bjerknes argued that forecasting should be treated as a problem of physics. If the present state of the atmosphere could be measured accurately, he reasoned, the laws governing the movement of air, heat and moisture could be used to calculate its future state. The British mathematician Lewis Fry Richardson attempted exactly this during the First World War, working out a forecast for a single region entirely by hand. The calculation took him about six weeks to complete for a forecast covering just six hours, and the result was wildly inaccurate. Later analysis showed that the problem lay mainly in his starting data rather than in his method. Undeterred, Richardson imagined a vast ''forecast factory'' in which tens of thousands of people would perform the calculations together, fast enough to keep ahead of the weather."}, {"label": "D", "text": "Richardson''s dream became practical only with the arrival of electronic computers. In 1950, a team of meteorologists and mathematicians in the United States used one of the earliest computers, ENIAC, to produce the first successful numerical forecast. It was a modest achievement by modern standards: the machine took roughly twenty-four hours to calculate a forecast covering the following twenty-four hours. Nevertheless, it proved that Bjerknes and Richardson had been right in principle. A decade later, a second revolution began from above. In 1960 the satellite TIROS-1 sent back the first television pictures of clouds taken from space, allowing forecasters to watch storms developing over oceans where there were few or no observations."}, {"label": "E", "text": "As computers grew more powerful, forecasters discovered a fundamental limit. In the 1960s the American meteorologist Edward Lorenz found that his computer model of the atmosphere was extremely sensitive to its starting conditions: rounding a single number slightly produced a completely different forecast a few weeks later. This property, later popularly known as the butterfly effect, means that small errors in measurement inevitably grow over time. Modern forecasting centres respond to this uncertainty by running their models many times with slightly different starting conditions. The resulting collection of forecasts, called an ensemble, shows how confident forecasters can be, and allows them to express predictions as probabilities, such as a seventy per cent chance of rain, which the writer considers a more honest way of communicating uncertainty than a single definite prediction."}, {"label": "F", "text": "The progress of the past half-century has nonetheless been remarkable. Studies of forecast accuracy suggest that skill has improved by about one day per decade, so that a forecast for several days ahead today is roughly as reliable as a forecast for one day fewer was ten years earlier. Better observations, faster computers and improved models have all contributed. Recently, machine-learning systems trained on decades of past weather data have begun to be tested alongside traditional models, and some have produced impressive results. Chaos, however, still sets a limit: beyond about two weeks, detailed day-to-day forecasts lose almost all their skill. Forecasters may yet predict the general character of a coming season, but the writer is doubtful that the weather will ever be predicted in full detail weeks in advance."}]'::jsonb,
     816, 'medium', 'Meteorology and the history of science', ARRAY['IELTS Reading', 'Original practice'], 'custom', ARRAY['academic']),
    ('rp-ir86-deepsea', 'ielts-2026-01', 'Oases of the Abyss: The Ecosystems of Hydrothermal Vents', 'Life flourishing in total darkness powered by geothermal chemistry',
     '[{"label": "A", "text": "Until the final decades of the twentieth century, biological dogma held that virtually all complex multicellular life on Earth was ultimately powered by solar radiation through the photosynthetic machinery of plants and phytoplankton. The abyssal ocean floor, shrouded in perpetual darkness thousands of metres beneath the surface, was presumed to be a biological wasteland, sustaining only sparse scavenger populations that subsisted on the meagre organic debris—known as marine snow—drifting down from the sunlit epipelagic zone. This long-standing paradigm was shattered in 1977 during an exploratory dive by the three-person research submersible Alvin along the Galápagos Rift. Deep on the volcanic seafloor, oceanographers were astonished to discover dense, thriving biological communities clustered around towering mineral chimneys spewing billowing black plumes of superheated fluid into the icy bottom water, completely upending prevailing ecological assumptions."}, {"label": "B", "text": "These volcanic structures, colloquially dubbed ''black smokers'', are hydrothermal vents formed along mid-ocean tectonic spreading ridges where Earth''s tectonic plates pull apart. Seawater percolates deep into cracks in the oceanic crust, where it is superheated by underlying magma chambers to temperatures exceeding four hundred degrees Celsius. Under extreme hydrostatic pressure—often exceeding two hundred atmospheres—the trapped water cannot boil into steam; instead, it becomes a chemically reactive supercritical fluid that leaches sulfur, iron, copper, and zinc from the surrounding basalt. Buoyant and superheated, this mineral broth rushes back up through the seabed. As it erupts into the near-freezing deep oceanic water, dissolved metal sulfides instantly precipitate out of solution, constructing hollow mineral chimneys that can soar several storeys high, composed of minerals like pyrite and chalcopyrite."}, {"label": "C", "text": "The foundation of the entire hydrothermal vent food web rests upon an alternative metabolic process: chemosynthesis. In the absolute absence of sunlight, specialized autotrophic bacteria and archaea oxidize reduced inorganic compounds—primarily toxic hydrogen sulfide and dissolved methane—to synthesize glucose and organic molecules from carbon dioxide. These chemolithoautotrophic microbes form dense microbial mats coating rock surfaces and billow in the thermal plumes, creating an abundant nutritional foundation. Vent animals graze directly upon these bacterial mats or filter them from the water, while predatory decapod crustaceans, zoarcid fish, and cephalopods hunt the primary consumers, forming an intricate trophic hierarchy independent of solar energy, thriving in waters where temperatures drop from boiling to freezing across mere centimetres."}, {"label": "D", "text": "The most striking evolutionary marvel of the vent ecosystem is the giant tube worm (Riftia pachyptila), which can grow to lengths exceeding two metres within flexible white chitinous tubes anchored to the volcanic rock. Anatomically bizarre, adult Riftia possess neither a mouth, nor a gut, nor an anus, and are completely incapable of ingesting food. Instead, the worm''s interior cavity is packed with a vascularized organ called a trophosome, which houses billions of endosymbiotic sulfur-oxidizing bacteria. The worm''s bright red, feathery plume absorbs hydrogen sulfide, oxygen, and carbon dioxide from the surrounding hydrothermal plume, utilizing specialized hemoglobin molecules that bind both oxygen and sulfide simultaneously without being poisoned. The bacteria process these raw chemical building blocks to manufacture organic nutrients, feeding the worm entirely from within."}, {"label": "E", "text": "Despite their remarkable local biomass, hydrothermal vent communities are geologically ephemeral oases separated by vast, hostile abyssal plains. Because mid-ocean volcanic systems are dynamic and unstable, individual vent chimneys frequently clog with mineral deposits or are extinguished abruptly when subterranean magma shifts, starving the local ecosystem within years. Consequently, vent species have evolved extraordinary reproductive strategies to colonize newly opening fissures kilometres away. Organisms release vast quantities of planktonic larvae that enter deep oceanic currents; capable of surviving for months in near-freezing temperatures by slowing their metabolic rates, these larvae navigate by detecting minute thermal anomalies, acoustic vibrations, and chemical plumes drifting from distant active chimneys, occasionally using intermediate whale falls as biological stepping stones."}, {"label": "F", "text": "In the twenty-first century, these pristine abyssal ecosystems face unprecedented commercial threats from the emerging deep-seabed mining industry. The mineral chimneys and seafloor deposits surrounding inactive hydrothermal vents consist of seafloor massive sulfides, which contain extraordinarily high concentrations of valuable industrial metals, including copper, gold, silver, and cobalt, essential for electric vehicles and renewable energy storage. Mining consortia are currently testing robotic seafloor crawlers designed to crush chimneys and vacuum mineral slurry to surface support ships. Marine scientists warn that stripping the seabed could devastate unique endemic species before science has even catalogued them. Developing rigorous environmental regulations under the International Seabed Authority represents an urgent diplomatic challenge to protect these fragile evolutionary marvels from industrial exploitation."}]'::jsonb,
     735, 'medium', 'Marine biology and oceanography', ARRAY['IELTS Reading', 'Original practice'], 'custom', ARRAY['academic'])
ON CONFLICT (id) DO NOTHING;

